<?php include 'db.php'; require_role('Patient'); $pid=current_entity_id($conn,'Patient'); $msg=''; if($_SERVER['REQUEST_METHOD']=='POST'){ $stmt=$conn->prepare("INSERT INTO APPOINTMENT(Appointment_Date,Appointment_Time,Status,Patient_ID,Doctor_ID,Nurse_ID,Test_ID,Room_ID) VALUES(?,?,'Booked',?,?,?,?,?)"); $stmt->bind_param('ssiiiii',$_POST['date'],$_POST['time'],$pid,$_POST['doctor'],$_POST['nurse'],$_POST['test'],$_POST['room']); if($stmt->execute()) $msg='Appointment booked successfully'; else $msg='Error: '.$conn->error; } $page_title='Book Appointment'; include 'header.php'; ?>
<h2>Book Appointment</h2><?php if($msg) echo '<div class="alert">'.esc($msg).'</div>'; ?>
<form class="form" method="post"><label>Date</label><input type="date" name="date" required><label>Time</label><input type="time" name="time" required><label>Doctor</label><select name="doctor"><?php $q=$conn->query("SELECT Doctor_ID, CONCAT(First_Name,' ',Last_Name) n FROM DOCTOR"); while($r=$q->fetch_assoc()) echo '<option value="'.$r['Doctor_ID'].'">'.esc($r['n']).'</option>'; ?></select><label>Nurse</label><select name="nurse"><?php $q=$conn->query("SELECT Nurse_ID, CONCAT(First_Name,' ',Last_Name) n FROM NURSE"); while($r=$q->fetch_assoc()) echo '<option value="'.$r['Nurse_ID'].'">'.esc($r['n']).'</option>'; ?></select><label>Radiology Test</label><select name="test"><?php $q=$conn->query("SELECT * FROM RADIOLOGY_TEST"); while($r=$q->fetch_assoc()) echo '<option value="'.$r['Test_ID'].'">'.esc($r['Test_Name'].' - '.$r['Price']).'</option>'; ?></select><label>Room</label><select name="room"><?php $q=$conn->query("SELECT * FROM ROOM"); while($r=$q->fetch_assoc()) echo '<option value="'.$r['Room_ID'].'">'.esc($r['Room_Name']).'</option>'; ?></select><button>Book Appointment</button></form>
<?php include 'footer.php'; ?>